  @("064_misumaru_tamatsukuri_a.png","https://en.touhouwiki.net/wiki/Special:FilePath/Th18Misumaru.png"),
  @("065_keiki_haniyasushin_a.png","https://en.touhouwiki.net/wiki/Special:FilePath/Th17Keiki.png"),
  @("066_junko_a.png","https://en.touhouwiki.net/wiki/Special:FilePath/Th15Junko.png"),
  @("067_sagume_kishin_a.png","https://en.touhouwiki.net/wiki/Special:FilePath/Th15Sagume.png"),
  @("opener_touhou_a.jpg","https://en.touhouwiki.net/wiki/Special:FilePath/Th10cover.jpg"),
  @("080_mystra_a.png","https://forgottenrealms.fandom.com/wiki/Special:FilePath/BG3_Mystra.png"),
  @("080_mystra_b.png","https://forgottenrealms.fandom.com/wiki/Special:FilePath/Elminster_and_mystra.png"),
  @("082_shar_a.jpg","https://forgottenrealms.fandom.com/wiki/Special:FilePath/Avatar_of_shar.jpg"),
  @("083_bahamut_a.jpg","https://forgottenrealms.fandom.com/wiki/Special:FilePath/Bahamut.jpg"),
  @("083_bahamut_b.jpg","https://forgottenrealms.fandom.com/wiki/Special:FilePath/Aspect_of_Bahamut.jpg"),
  @("085_lolth_a.jpg","https://forgottenrealms.fandom.com/wiki/Special:FilePath/Descent_Lolth_avatar.jpg"),
  @("opener_dnd_a.jpg","https://forgottenrealms.fandom.com/wiki/Special:FilePath/Dark_Seldarine_-_F%26P.jpg"),
  @("opener_dnd_b.jpg","https://forgottenrealms.fandom.com/wiki/Special:FilePath/Elven_Pantheon.jpg")
)
foreach ($f in $files) {
  $dest = Join-Path $out $f[0]; $ok = $false
  if ((Test-Path $dest) -and ((Get-Item $dest).Length -gt 2000)) { continue }
  for ($a=0; $a -lt 3 -and -not $ok; $a++) {
    try { Invoke-WebRequest -Uri $f[1] -OutFile $dest -UserAgent $UA -MaximumRedirection 10 -TimeoutSec 60; if ((Get-Item $dest).Length -gt 2000) { $ok = $true } } catch {}
    if (-not $ok) { Start-Sleep -Seconds (2 + 3*$a) }
  }
  if ($ok) { Write-Host "ok    $($f[0])" } else { Write-Host "FAIL  $($f[0])"; $failed += "$($f[0])`t$($f[1])"; Remove-Item $dest -ErrorAction SilentlyContinue }
  Start-Sleep -Milliseconds 1000
}
$failed | Out-File -Encoding utf8 (Join-Path $out "_failed.txt")
$zip = Join-Path $PSScriptRoot "unwilling_saint_art.zip"; if (Test-Path $zip) { Remove-Item $zip }
Compress-Archive -Path $out -DestinationPath $zip
Write-Host ""; Write-Host "Done. $($files.Count - $failed.Count) of $($files.Count) downloaded. Upload unwilling_saint_art.zip to the chat."
Read-Host "Press Enter to close"